def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less than 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    count = 0
    for i in range(2, a + 1):
        if is_prime(i) and a % i == 0:
            count += 1
            # Divide out all factors of i
            while a % i == 0:
                a //= i
        if a == 1:
            break
    # After factoring out all prime factors, check if exactly 3 prime factors were involved
    # and the original number was divisible by exactly three primes
    # To do this properly, we need to count the number of prime factors (with multiplicity)
    # Let's re-implement with factorization
    def prime_factors(n):
        factors = []
        for i in range(2, n + 1):
            while n % i == 0:
                factors.append(i)
                n //= i
        return factors

    factors = prime_factors(a)
    return len(factors) == 3
```

