import heapq

def large_product(list1, list2, n):
    # Use a max heap by inserting negative products
    max_heap = []
    for a in list1:
        for b in list2:
            heapq.heappush(max_heap, -(a * b))
    result = []
    for _ in range(min(n, len(max_heap))):
        result.append(-heapq.heappop(max_heap))
    return result
