def pancake_sort(arr):
    def flip(sublist, k):
        return sublist[:k][::-1] + sublist[k:]

    n = len(arr)
    for size in range(n, 1, -1):
        # Find index of the maximum element in arr[0..size-1]
        max_idx = arr.index(max(arr[:size]))
        if max_idx != size - 1:
            # Flip max element to front if it's not already at front
            if max_idx != 0:
                arr = flip(arr, max_idx + 1)
            # Flip it to its correct position
            arr = flip(arr, size)
    return arr
```

