def start_withp(words):
    for word in words:
        # Split the string into individual words
        split_words = word.split()
        for w in split_words:
            if w.startswith('P'):
                # Return the first two words starting with 'P'
                p_words = [w]
                # Continue searching for the next word starting with 'P'
                for next_w in split_words[split_words.index(w)+1:]:
                    if next_w.startswith('P'):
                        p_words.append(next_w)
                        break
                # If only one found, look in the remaining list
                if len(p_words) < 2:
                    for next_w in split_words[split_words.index(w)+1:]:
                        if next_w.startswith('P'):
                            p_words.append(next_w)
                            break
                # If still less than 2, continue searching in other strings
                if len(p_words) < 2:
                    continue
                return tuple(p_words[:2])
    return None
```

