def max_sum_increasing_subseq(arr, n, i, k):
    # Calculate the maximum sum of increasing subsequence up to index i
    max_sum_up_to_i = [0] * (i + 1)

    for j in range(i + 1):
        max_sum_up_to_i[j] = arr[j]
        for l in range(j):
            if arr[l] < arr[j]:
                max_sum_up_to_i[j] = max(max_sum_up_to_i[j], max_sum_up_to_i[l] + arr[j])

    # Now include the kth element
    max_sum_with_k = 0
    for j in range(i + 1):
        if arr[j] < arr[k]:
            max_sum_with_k = max(max_sum_with_k, max_sum_up_to_i[j] + arr[k])

    return max_sum_with_k

