def encode(message):
    def shift_vowel(v):
        vowels = 'aeiou'
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
        index = vowels.index(v.lower())
        shifted_char = alphabet[(index + 2) % 5]
        return shifted_char

    result = []
    for ch in message:
        if ch.isalpha():
            # Swap case
            swapped = ch.swapcase()
            # Replace vowels
            if swapped.lower() in 'aeiou':
                new_char = shift_vowel(swapped)
                # Preserve original case
                new_char = new_char.upper() if swapped.isupper() else new_char
                result.append(new_char)
            else:
                result.append(swapped)
        else:
            result.append(ch)
    return ''.join(result)
