def compare_one(a, b):
    def parse_value(val):
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            s = val.replace(',', '.')
            try:
                return float(s)
            except ValueError:
                return None
        else:
            return None

    a_val = parse_value(a)
    b_val = parse_value(b)

    # If either parsing failed, compare original values
    if a_val is None or b_val is None:
        # Check if both are strings
        if isinstance(a, str) and isinstance(b, str):
            if a == b:
                return None
            return a if a > b else b
        # If one is string and the other is number, compare as strings
        elif isinstance(a, str) and not isinstance(b, str):
            if a == str(b):
                return None
            return a if a > str(b) else b
        elif not isinstance(a, str) and isinstance(b, str):
            if str(a) == b:
                return None
            return a if str(a) > b else b
        else:
            # Fallback: compare as original
            if a == b:
                return None
            return a if a > b else b
    else:
        # Both parsed successfully as numbers
        if a_val == b_val:
            return None
        return a if a_val > b_val else b
