def search(nums):
    left, right = 0, len(nums) - 1

    while left < right:
        mid = left + (right - left) // 2

        # Check if mid is even or odd
        if mid % 2 == 0:
            if mid + 1 < len(nums) and nums[mid] == nums[mid + 1]:
                left = mid + 2
            else:
                right = mid
        else:
            if mid - 1 >= 0 and nums[mid] == nums[mid - 1]:
                left = mid + 1
            else:
                right = mid

    return nums[left]

