def set_left_most_unset_bit(n):
    # Find the position of the highest set bit
    highest_bit = n.bit_length()
    # Create a mask with all bits up to highest_bit
    all_ones = (1 << highest_bit) - 1
    # Find the first unset bit from the left
    for position in range(highest_bit - 1, -1, -1):
        if not (n & (1 << position)):
            # Set this bit
