def max_sum_increasing_subseq(arr, n, i, k):
    # Initialize DP array where dp[j] will hold the maximum sum of increasing subsequence ending at index j
    dp = arr.copy()

    # Compute maximum sum of increasing subsequence ending at each index
    for j in range(n):
        for l in range(j):
            if arr[l] < arr[j]:
                dp[j] = max(dp[j], dp[l] + arr[j])

    # Find the maximum sum of increasing subsequence up to index i (inclusive)
    max_sum_up_to_i = max(dp[:i+1]) if i >= 0 else 0

    # Ensure that arr[k] > arr[i] to satisfy the increasing sequence condition
    if k >= n or k <= i or arr[k] <= arr[i]:
        return 0  # or handle as per requirements

    # Find the maximum sum of increasing subsequence starting from index k
    # We do this by considering subsequences starting at k and extending forward
    # For this, we can process from k to end
    max_sum_from_k = arr[k]
    for j in range(k+1, n):
        if arr[j] > arr[k]:
            max_sum_from_k = max(max_sum_from_k, arr[k] + max_sum_increasing_subseq(arr, n, j, k))

    # Alternatively, since the subsequence must include arr[k], and be increasing from i to k,
    # and then continue from k onwards, we can process as follows:

    # Find the maximum sum of increasing subsequence starting at k
    # For this, process from k to end
    max_sum_starting_at_k = arr[k]
    for j in range(k+1, n):
        if arr[j] > arr[k]:
