def find_solution(a, b, n):
    from math import gcd

    # Check if the equation has a solution
    d = gcd(a, b)
    if n % d != 0:
        return None

    # Extended Euclidean Algorithm to find one solution
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, x1, y1 = extended_gcd(y, x % y)
            return (g, y1, x1 - (x // y) * y1)

    g, x0, y0 = extended_gcd(a, b)

    # Scale the solution to match n
    x0 *= n // d
    y0 *= n // d

    # Adjust solutions to find non-negative integers if needed
    # (Optional: if only any integer solution is needed, return directly)
    return (x0, y0)
```

