def max_sub_array_sum_repeated(arr, n, k):
    def kadane(array):
        max_ending_here = max_so_far = array[0]
        for num in array[1:]:
            max_ending_here = max(num, max_ending_here + num)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(arr)
    max_subarray_sum_single = kadane(arr)

    if k == 1:
        return max_subarray_sum_single

    # For k >= 2, consider the possibility of wrapping around
    # Compute max prefix sum
    max_prefix_sum = current_sum = 0
    for num in arr:
        current_sum += num
        max_prefix_sum = max(max_prefix_sum, current_sum)

    # Compute max suffix sum
    max_suffix_sum = current_sum = 0
    for num in arr[::-1]:
        current_sum += num
        max_suffix_sum = max(max_suffix_sum, current_sum)

    if total_sum > 0:
        # The maximum sum can be the sum of suffix + prefix + (k-2)*total_sum
        return max(max_subarray_sum_single, max_suffix_sum + max_prefix_sum + (k - 2) * total_sum)
    else:
        # When total sum <= 0, the maximum sum is within two concatenations
        return max(max_subarray_sum_single, max_suffix_sum + max_prefix_sum)
