def is_samepatterns(sequence, patterns):
    if len(sequence) != len(patterns):
        return False

    pattern_mapping = {}
    used_patterns = set()

    for item, pattern in zip(sequence, patterns):
        if pattern not in pattern_mapping:
            if pattern in used_patterns:
                # pattern already assigned to a different item
                return False
            pattern_mapping[pattern] = item
            used_patterns.add(pattern)
        else:
            if pattern_mapping[pattern] != item:
                return False
    return True
