def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Arrays to store the maximum sum of increasing subsequence ending at each index
    inc = arr.copy()
    # Arrays to store the maximum sum of decreasing subsequence starting at each index
    dec = arr.copy()

    # Compute the maximum sum of increasing subsequence ending at each index
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Compute the maximum sum of decreasing subsequence starting at each index
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum_bitonic = 0
    for i in range(n):
        # Subtract arr[i] once because it's counted in both inc and dec
        current_sum = inc[i] + dec[i] - arr[i]
        if current_sum > max_sum_bitonic:
            max_sum_bitonic = current_sum

    return max_sum_bitonic

# Test cases
assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194
assert max_sum([80, 60, 30, 40, 20, 10]) == 210
assert max_sum([2, 3, 14, 16, 21, 23, 29, 30]) == 138
```

