def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        total = 1
        sqrt_n = int(n**0.5)
        for i in range(2, sqrt_n + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total

    total_sum = 0
    for num in range(2, limit + 1):
        s = sum_of_divisors(num)
        if s != num and s <= limit:
            if sum_of_divisors(s) == num:
                total_sum += num
    return total_sum
```

