def sum_of_divisors(n):
    total = 1  # Start with 1 because 1 is a divisor of every number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def amicable_numbers_sum(limit):
    amicable_numbers = set()

    for num in range(2, limit + 1):
        if num not in amicable_numbers:
            partner = sum_of_divisors(num)
            if partner != num and sum_of_divisors(partner) == num:
                amicable_numbers.add(num)
                amicable_numbers.add(partner)

    return sum(amicable_numbers)

# Test cases
assert amicable_numbers_sum(999) == 504
assert amicable_numbers_sum(9999) == 31626
assert amicable_numbers_sum(99) == 0
```

